import { useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent } from "react";
import { useIsomorphicLayoutEffect } from "../../primitives";

export type Continent = "north-america" | "south-america" | "europe" | "africa" | "asia" | "oceania";

/** Props for AfWorldMap. */
export type AfWorldMapProps = {
  /** Shown continent (controlled) */
  continent?: Continent;
  /** Continent shown first when `continent` is not set */
  defaultContinent?: Continent;
  /** Called when the viewer picks a continent in the menu */
  onContinentChange?: (continent: Continent) => void;
  /** Show the continent menu in the top-left corner */
  showSwitcher?: boolean;
  /** Accessible description of the map; a function receives the current continent */
  label?: string | ((continent: Continent) => string);
  /** Extra class on the root */
  className?: string;
  /** Inline styles on the root */
  style?: CSSProperties;
};

const OPTIONS: { value: Continent; name: string; label: string }[] = [
  { value: "north-america", name: "North America", label: "World map with North America highlighted" },
  { value: "south-america", name: "South America", label: "World map with South America highlighted" },
  { value: "europe", name: "Europe", label: "World map with Europe highlighted" },
  { value: "africa", name: "Africa", label: "World map with Africa highlighted" },
  { value: "asia", name: "Asia", label: "World map with Asia highlighted" },
  { value: "oceania", name: "Oceania", label: "World map with Oceania highlighted" },
];

type Phase = "idle" | "enter" | "exit";

/** World map with one highlighted continent and a pastel band along its coastline, switchable between all six. */
export function AfWorldMap({
  continent,
  defaultContinent = "europe",
  onContinentChange,
  showSwitcher = true,
  label,
  className,
  style,
}: AfWorldMapProps = {}) {
  const id = "ui-wm" + useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const root = useRef<HTMLDivElement>(null);
  const [own, setOwn] = useState<Continent>(defaultContinent);
  const current = continent ?? own;
  const option = OPTIONS.find((o) => o.value === current) ?? OPTIONS[2];

  const select = (next: Continent) => {
    if (continent === undefined) setOwn(next);
    if (next !== current) onContinentChange?.(next);
  };

  const [layers, setLayers] = useState<{ key: number; continent: Continent; phase: Phase }[]>([
    { key: 0, continent: current, phase: "idle" },
  ]);
  useEffect(() => {
    setLayers((all) => {
      const top = all[all.length - 1];
      if (top.continent === current) return all;
      return [
        ...all.map((l) => ({ ...l, phase: "exit" as Phase })),
        { key: top.key + 1, continent: current, phase: "enter" as Phase },
      ];
    });
  }, [current]);
  useEffect(() => {
    if (!layers.some((l) => l.phase === "exit")) return;
    const timer = setTimeout(() => setLayers((all) => all.filter((l) => l.phase !== "exit")), 360);
    return () => clearTimeout(timer);
  }, [layers]);

  const [scale, setScale] = useState(1);
  useEffect(() => {
    const el = root.current;
    if (!el) return;
    const fit = () => setScale(Math.min(1, Math.max(0.62, el.clientWidth / 540)));
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={root}
      className={["ui-wm", className].filter(Boolean).join(" ")}
      style={{ "--ui-wm-s": scale, ...style } as CSSProperties}
    >
      <div
        className="ui-wm-map"
        role="img"
        aria-label={typeof label === "function" ? label(current) : (label ?? option.label)}
      >
        <svg className="ui-wm-art" viewBox="0 0 540 242" aria-hidden="true">
          <defs>
            <filter id={`${id}-shadow`} x="-15%" y="-15%" width="130%" height="130%">
              <feDropShadow className="ui-wm-drop" dx="0" dy="2" stdDeviation="2.5" floodColor="#1F2128" floodOpacity="0.1" />
            </filter>
            <linearGradient id={`${id}-shine`} gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="540" y2="242">
              <stop offset="0%" stopColor="#FFA0AB" />
              <stop offset="33%" stopColor="#FFB89E" />
              <stop offset="66%" stopColor="#C8A8E5" />
              <stop offset="100%" stopColor="#A8B5FF" />
            </linearGradient>
            <filter id={`${id}-blur`} x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="4" />
            </filter>
          </defs>
          <g className="ui-wm-land" fill="#E8E8E8" stroke="#E8E8E8" strokeWidth="0.5" strokeLinejoin="round">
            {LAND_PATHS.map((d, idx) => (
              <path key={idx} d={d} />
            ))}
          </g>
          {layers.map((l) => (
            <MapLayer key={l.key} id={`${id}-${l.key}`} shared={id} continent={l.continent} phase={l.phase} />
          ))}
        </svg>
      </div>
      {showSwitcher && <Switcher value={current} onChange={select} />}
    </div>
  );
}

function MapLayer({ id, shared, continent, phase }: { id: string; shared: string; continent: Continent; phase: Phase }) {
  const map = CONTINENT_MAPS[continent];
  const landD = LAND_PATHS[map.landIdx];
  return (
    <g className="ui-wm-layer" data-phase={phase} style={{ transformOrigin: map.origin }}>
      <defs>
        <mask id={`${id}-outside`} maskUnits="userSpaceOnUse" x="0" y="0" width="540" height="242">
          <rect x="0" y="0" width="540" height="242" fill="#FFFFFF" />
          <path d={landD} fill="#000000" />
        </mask>
      </defs>
      <path
        d={landD}
        filter={`url(#${shared}-shadow)`}
        className="ui-wm-focus"
        fill="#FFFFFF"
        stroke="#E2E2E2"
        strokeWidth="0.5"
        strokeLinejoin="round"
      />
      <g fill="none" stroke={`url(#${shared}-shine)`} strokeLinecap="round" strokeLinejoin="round">
        <path
          className="ui-wm-band"
          d={map.perimeter}
          pathLength={1000}
          strokeWidth="6"
          strokeDasharray="180 820"
          filter={`url(#${shared}-blur)`}
          mask={`url(#${id}-outside)`}
          opacity="0.45"
        />
        <path className="ui-wm-band" d={map.perimeter} pathLength={1000} strokeWidth="1.4" strokeDasharray="200 800" opacity="0.32" />
        <path
          className="ui-wm-band ui-wm-band--1"
          d={map.perimeter}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="140 860"
          strokeDashoffset="-30"
          opacity="0.55"
        />
        <path
          className="ui-wm-band ui-wm-band--2"
          d={map.perimeter}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="80 920"
          strokeDashoffset="-60"
        />
      </g>
    </g>
  );
}

function Switcher({ value, onChange }: { value: Continent; onChange: (continent: Continent) => void }) {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const [glide, setGlide] = useState(false);
  const [from, setFrom] = useState({ w: 88, h: 28 });
  const [box, setBox] = useState({ y: 0, h: 32 });

  const menuId = "ui-wm-menu" + useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const wrap = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const items = useRef<(HTMLDivElement | null)[]>([]);
  const selected = OPTIONS.find((o) => o.value === value) ?? OPTIONS[2];

  const openMenu = (focusSelected: boolean) => {
    if (trigger.current) setFrom({ w: trigger.current.offsetWidth, h: trigger.current.offsetHeight });
    setGlide(false);
    setActive(focusSelected ? OPTIONS.findIndex((o) => o.value === value) : -1);
    setOpen(true);
  };

  const closeMenu = (returnFocus = false) => {
    setOpen(false);
    setActive(-1);
    if (returnFocus) trigger.current?.focus();
  };

  const pick = (continent: Continent, returnFocus = false) => {
    onChange(continent);
    closeMenu(returnFocus);
  };

  useIsomorphicLayoutEffect(() => {
    const el = items.current[active];
    if (el) setBox({ y: el.offsetTop, h: el.offsetHeight });
  }, [active, open]);

  useEffect(() => {
    if (open) panel.current?.focus({ preventScroll: true });
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const onDown = (e: PointerEvent) => {
      if (!wrap.current?.contains(e.target as Node)) closeMenu();
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [open]);

  const onTriggerKey = (e: KeyboardEvent) => {
    if (e.key === "ArrowDown" || e.key === "ArrowUp" || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      openMenu(true);
    }
  };

  const onPanelKey = (e: KeyboardEvent) => {
    if (e.key === "Escape") {
      e.preventDefault();
      closeMenu(true);
    } else if (e.key === "Tab") {
      closeMenu();
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      setGlide(active >= 0);
      setActive((i) => (i + 1) % OPTIONS.length);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setGlide(active >= 0);
      setActive((i) => (i <= 0 ? OPTIONS.length - 1 : i - 1));
    } else if (e.key === "Home") {
      e.preventDefault();
      setGlide(active >= 0);
      setActive(0);
    } else if (e.key === "End") {
      e.preventDefault();
      setGlide(active >= 0);
      setActive(OPTIONS.length - 1);
    } else if ((e.key === "Enter" || e.key === " ") && active >= 0) {
      e.preventDefault();
      pick(OPTIONS[active].value, true);
    }
  };

  return (
    <div ref={wrap} className="ui-wm-switch">
      <button
        ref={trigger}
        type="button"
        className="ui-wm-trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={menuId}
        aria-label={`Continent: ${selected.name}`}
        onClick={() => (open ? closeMenu() : openMenu(false))}
        onKeyDown={onTriggerKey}
      >
        <span>{selected.name}</span>
        <svg className="ui-wm-chevron" viewBox="0 0 14 14" fill="none" aria-hidden="true">
          <path
            className="ui-wm-chevron-ink"
            d="M3.75 5.5 7 8.75 10.25 5.5"
            stroke="#737373"
            strokeWidth="1.4"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>

      <div
        className="ui-wm-menu"
        data-open={open}
        aria-hidden={!open}
        style={{ "--from-w": `${from.w}px`, "--from-h": `${from.h}px` } as CSSProperties}
      >
        <div
          ref={panel}
          id={menuId}
          role="listbox"
          tabIndex={-1}
          aria-label="Continent"
          aria-activedescendant={open && active >= 0 ? `${menuId}-${active}` : undefined}
          className="ui-wm-panel"
          onKeyDown={onPanelKey}
          onPointerLeave={() => {
            setActive(-1);
            setGlide(false);
          }}
        >
          <div
            aria-hidden="true"
            className="ui-wm-fill"
            data-glide={glide}
            style={{ transform: `translateY(${box.y}px)`, height: box.h, opacity: active >= 0 ? 1 : 0 }}
          />
          {OPTIONS.map((o, i) => (
            <div
              key={o.value}
              id={`${menuId}-${i}`}
              ref={(el) => {
                items.current[i] = el;
              }}
              role="option"
              aria-selected={o.value === value}
              className="ui-wm-option"
              onPointerEnter={() => {
                setGlide(active >= 0);
                setActive(i);
              }}
              onClick={() => pick(o.value)}
            >
              <span className="ui-wm-option-name">{o.name}</span>
              <span className="ui-wm-check" aria-hidden="true">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <path d="M5 14L8.5 17.5L19 6.5" />
                </svg>
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

